/// Convenience overloads for operation inputs.
extension APIProtocol {
    /// Health check
    ///
    /// - Remark: HTTP `GET /healthz`.
    /// - Remark: Generated from `#/paths//healthz/get(healthz)`.
    public func healthz() async throws -> Operations.Healthz.Output {
        try await healthz(Operations.Healthz.Input())
    }
    /// Readiness check
    ///
